  ('zuitzerland', 'Zuitzerland', 'May 1 - May 26, 2025', 'Laax, Switzerland', '[9.2581, 46.8064]'::jsonb, 'A Zuzalu and d/acc offshoot running month-long residencies in the Swiss Alps, using Swiss direct democracy as a sandbox for network-state and governance experiments. The long-term aim is a permanent Swiss Zuzalu node.', 'popup', 'https://www.zuitzerland.ch/', 'https://x.com/zuitzerland', 'https://t.me/Zuitzerland', 'https://cdn.buttercms.com/lMAkM1WSnq8JQNYXfjj3', 'https://cdn.buttercms.com/inc5SP3ySAODhxCVR2MA', false),
  ('ayahq', 'AyaHQ', 'Permanent', 'Accra, Ghana', '[-0.2059, 5.7328]'::jsonb, 'An African startup incubator with builder hubs in Accra and Kilifi, Kenya, offering co-working, residencies and incubation cohorts. Its Accra hub is in Abokobi.', 'permanent', 'https://www.ayahq.com/', 'https://x.com/ayahq_', NULL, 'https://www.ayahq.com/apple-touch-icon.png', 'https://ayahq.com/opengraph-image?7ae89683254cb1e2', false),
  ('crecimiento', 'Crecimiento', 'Permanent', 'Buenos Aires, Argentina', '[-58.4898, -34.5466]'::jsonb, 'A Buenos Aires foundation growing Argentina''s crypto, AI and tech scene. It runs Aleph Hub, a permanent co-working space, and hosts the recurring Aleph pop-up city and hackathon.', 'permanent', 'https://crecimiento.build/', 'https://x.com/crecimientoar', 'https://t.me/+UfzEgPbzXB43ZjE0', 'https://crecimiento.build/icon.png', 'https://crecimiento.build/og.jpg', false),
  ('proof-of-retreat', 'Proof of Retreat', 'Jan 3 - Feb 3, 2027', 'Vĩnh Hải, Khánh Hòa, Vietnam', '[109.1471268, 11.6154176]'::jsonb, 'A month-long pop-up village and hacker house built around phone-free deep work, kitesurfing, shared meals and recovery. Edition #4 is on the Khánh Hòa coast, straight after edition #3 in Chiang Mai.', 'popup', 'https://proofofretreat.me', 'https://x.com/proofofretreat', 'https://t.me/proofofretreat', 'https://proofofretreat.me/assets/img/logo.svg', NULL, false),
  ('arc-mirissa', 'Ârc', 'Permanent', 'Mirissa, Sri Lanka', '[80.45972, 5.94583]'::jsonb, 'A founder community and live-in accelerator on a beachfront campus in Mirissa, with pay-as-you-go membership. After pop-ups in Lisbon, Austin and Singapore, Ârc calls Sri Lanka its permanent home.', 'permanent', 'https://arc.lk', NULL, NULL, 'https://arc.lk/apple-touch-icon.png', NULL, false),
  ('web3clubs-nairobi', 'Web3Clubs', 'Permanent', 'Nairobi, Kenya', '[36.7810611, -1.2994604]'::jsonb, 'A Web3 incubator and builder hub in Nairobi with a physical space hosting developer education, founder sessions and community events, plus residencies run with partners.', 'permanent', 'https://luma.com/web3clubs', 'https://x.com/Web3Clubs', NULL, 'https://images.lumacdn.com/calendars/f2/6a760b23-92db-4c47-a1de-1ed224e504bb.png', NULL, false),
  ('viva-city-sf', 'Viva City', 'Permanent', 'San Francisco, CA, USA', '[-122.41, 37.7822]'::jsonb, 'A longevity-focused community working toward a city where people aim to beat aging. In San Francisco it runs an ongoing Longevity Floor inside Frontier Tower, with co-working, weekly events, a clinic and a startup incubator.', 'permanent', 'https://viva.city', 'https://x.com/CityOfViva', 'https://t.me/viva_city_updates', 'https://framerusercontent.com/images/kZ4ODVE2wLeu3K1f5uFfRfaOgpk.png', 'https://framerusercontent.com/assets/TEqO4GSr6ugOVczFpalrhbshm3w.png', false),
  ('kuu-village', 'kuu village', 'Oct 1 - Oct 7, 2025', 'Tsukigase, Nara, Japan', '[136.0442, 34.7095]'::jsonb, 'A week-long off-grid co-living experiment for about 40 people in rural Tsukigase, testing decentralized governance, a community currency and DIY builds. It calls itself a perma-pop-up that moves to a new host region each time.', 'popup', 'https://github.com/kuuvillage', NULL, NULL, 'https://avatars.githubusercontent.com/u/224917080?v=4', 'https://raw.githubusercontent.com/kuuvillage/.github/main/images/mainvisual.jpg', false),
  ('zugrama', 'Zu-Grama', 'Jan 5 - Feb 16, 2025', 'Thiruvananthapuram, Kerala, India', '[76.9583, 8.4972]'::jsonb, 'India''s first Zuzalu-inspired pop-up village: a six-week residency where 150+ builders, scientists and founders lived and worked together across governance, public goods, longevity, deep tech and cryptography.', 'popup', 'https://zugrama.org', 'https://x.com/zugramadotorg', NULL, 'https://zugrama.org/_framer/images/JjyabQTnD5xUw3feG17pN74jiXg.png', 'https://zugrama.org/_framer/images/wJDirYhhSH8znG0hz0hyH3wqOlE.png', false)
